package msnspi

import (
	"github.com/TheManticoreProject/Manticore/network/dcerpc/ndr"
)

// PropertyRow_r ([MS-NSPI] 2.2.4). Generated by tools/idlgen; verify pointer/array tags.
type PropertyRow_r struct {
	Reserved ndr.DWORD
	CValues  ndr.DWORD
	LpProps  []PropertyValue_r `ndr:"unique,size_is=CValues"`
}

// SetDiscriminants derives the PROP_VAL_UNION discriminant of every value in the row from
// its ulPropTag, so a caller-built row marshals wire-correctly.
func (p *PropertyRow_r) SetDiscriminants() {
	if p == nil {
		return
	}
	for i := range p.LpProps {
		p.LpProps[i].SetDiscriminant()
	}
}
